  useEffect(() => { if (params.get('type')) setActiveTab(params.get('type') === 'INPUT' ? 'INPUT' : 'OUTPUT'); },[params]);
  return <><div className="mb-5 flex gap-3">{(['OUTPUT', 'INPUT'] as const).map((type) => <Button key={type} variant={activeTab === type ? 'primary' : 'secondary'} onClick={() => { setActiveTab(type); setParams({type}); }}>{type === 'INPUT' ? (isEn ? 'Purchase Invoices (In)' : 'Hóa đơn mua vào (Chi)') : (isEn ? 'Sales Invoices (Out)' : 'Hóa đơn bán ra (Thu)')}</Button>)}</div><ResourcePage key={activeTab} fixedType={activeTab} entity="invoices" title={activeTab === 'INPUT' ? (isEn ? 'Purchase Invoices' : 'Hóa đơn mua vào') : (isEn ? 'Sales Invoices' : 'Hóa đơn bán ra')} description={isEn ? 'Itemized tax calculation; track settled and outstanding debt amounts.' : 'Tự tính thuế theo từng mặt hàng; theo dõi thanh toán và tiền còn nợ.'} icon={<FileCheck2 size={18}/>} columns={[{ key: 'code', label: isEn ? 'Invoice No.' : 'Số hóa đơn' }, { key: 'direction', label: isEn ? 'Type' : 'Loại', format: 'status' }, { key: 'counterparty', label: isEn ? 'Partner / Client' : 'Khách / người bán' }, { key: 'date', label: isEn ? 'Date' : 'Ngày', format: 'date' }, { key: 'subtotal', label: isEn ? 'Subtotal' : 'Tiền hàng', format: 'money' }, { key: 'taxAmount', label: isEn ? 'Tax' : 'Thuế', format: 'money' }, { key: 'total', label: isEn ? 'Total' : 'Tổng tiền', format: 'money' }, { key: 'openBalance', label: isEn ? 'Remaining Balance' : 'Còn nợ', format: 'money' }, { key: 'paymentStatus', label: isEn ? 'Payment' : 'Thanh toán', format: 'status' }, { key: 'status', label: isEn ? 'Status' : 'Trạng thái', format: 'status' }]} fields={[]} actions={(row) => row.direction === 'OUTPUT' && !['DEMO_CODE_ISSUED', 'CANCELLED'].includes(row.status || '') ? [{ label: isEn ? 'Issue Tax Code' : 'Cấp mã hóa đơn', action: 'simulate-code' }] : []} rowExtra={(row) => row.odooUrl ? <a href={row.odooUrl} target="_blank" rel="noreferrer" className="text-xs font-semibold text-brand-700">{isEn ? 'Open Odoo' : 'Mở Odoo'}</a> : null}/></>;
