  const [fxBusy,setFxBusy]=useState(false);
  const { language, setLanguage, t, isEn } = useLanguage();
  const provisionErp=async()=>{setFxBusy(true);try{const {data}=await api.post('/integrations/odoo/company');toast(data.message||(isEn ? 'Linked Odoo company.' : 'Đã liên kết công ty Odoo.'));await loadTab();}catch(error){toast(messageOf(error),'error');}finally{setFxBusy(false);}};
  const [searchParams] = useSearchParams();
  const [tab, setTab] = useState<'profile' | 'accounts' | 'users' | 'permissions' | 'rules' | 'classifications' | 'integrations' | 'audit' | 'language'>(() => (['profile','accounts','users','permissions','rules','classifications','integrations','audit','language'].includes(searchParams.get('tab') || '') ? searchParams.get('tab') : 'profile') as any);
  const [users, setUsers] = useState<any[]>([]); const [rolePermissions, setRolePermissions] = useState<any[]>([]); const [logs, setLogs] = useState<any[]>([]); const [integrations, setIntegrations] = useState<any>(null); const [queueRows, setQueueRows] = useState<any[]>([]); const [syncing, setSyncing] = useState(false); const [modal, setModal] = useState(false); const [passwordModal, setPasswordModal] = useState(false); const [loading, setLoading] = useState(false); const toast = useToast(); const { user } = useAuth();
  const loadTab = useCallback(async () => { setLoading(true); try { if (tab === 'users' && user?.role === 'OWNER') setUsers((await api.get('/users')).data); if (tab === 'permissions' && user?.role === 'OWNER') setRolePermissions((await api.get('/role-permissions')).data); if (tab === 'audit' && user?.role === 'OWNER') setLogs((await api.get('/audit-logs')).data); if (tab === 'integrations') { setIntegrations((await api.get('/integrations/status')).data); if (user?.role === 'OWNER') setQueueRows((await api.get('/integrations/odoo/queue')).data); } } catch (error) { toast(messageOf(error), 'error'); } finally { setLoading(false); } }, [tab, user?.role]);
  useEffect(() => { void loadTab(); }, [loadTab]);
  const addUser: FieldDef[] = [{ name: 'name', label: isEn ? 'Full Name' : 'Họ và tên', required: true }, { name: 'email', label: isEn ? 'Login Email' : 'Email đăng nhập', type: 'text', required: true }, { name: 'role', label: isEn ? 'Role' : 'Vai trò', type: 'select', required: true, options: [{ value: 'OWNER', label: isEn ? 'Owner / Manager' : 'Chủ xưởng / Quản lý' }, { value: 'ACCOUNTANT', label: isEn ? 'Accountant / Sales' : 'Kế toán / Bán hàng' }, { value:'WAREHOUSE',label: isEn ? 'Warehouse Keeper' : 'Thủ kho' }, { value: 'WORKSHOP', label: isEn ? 'Workshop Worker' : 'Thợ xưởng' }] }, { name: 'password',type:'password', label: isEn ? 'Temporary Password (at least 10 chars)' : 'Mật khẩu tạm thời (ít nhất 10 ký tự)', required: true, wide: true }];
  const addRule: FieldDef[] = [{ name: 'code', label: isEn ? 'Rule Code' : 'Mã quy tắc', required: true }, { name: 'name', label: isEn ? 'Rule Name' : 'Tên quy tắc', required: true }, { name: 'category', label: isEn ? 'Category' : 'Nhóm nghiệp vụ' }, { name: 'legalReference', label: isEn ? 'Legal Reference' : 'Nguồn tham khảo', wide: true }, { name: 'effectiveFrom', label: isEn ? 'Effective From' : 'Hiệu lực từ', type: 'date' }, { name: 'effectiveTo', label: isEn ? 'Effective To' : 'Hiệu lực đến', type: 'date' }, { name: 'status', label: isEn ? 'Status' : 'Trạng thái rà soát', type: 'select', options: [{ value: 'REVIEW_REQUIRED', label: isEn ? 'Review Required' : 'Cần rà soát' }, { value: 'ACTIVE', label: isEn ? 'Active' : 'Đã xác nhận áp dụng' }] }];
  const saveItem = async (value: Record<string, unknown>) => { try { if (tab === 'users') await api.post('/users', value); else if (tab === 'rules') await createRecord('tax-rules', value); setModal(false); toast(isEn ? 'Information saved.' : 'Đã lưu thông tin.'); await loadTab(); } catch (error) { throw new Error(messageOf(error)); } };
  const setUserActive = async (id: string, active: boolean) => { try { await api.patch(`/users/${id}/status`, { active }); toast(active ? (isEn ? 'Account activated.' : 'Đã mở tài khoản.') : (isEn ? 'Account locked.' : 'Đã khóa tài khoản.')); await loadTab(); } catch (error) { toast(messageOf(error), 'error'); } };
  const refreshFx=async()=>{setFxBusy(true);try{await api.post('/integrations/odoo/currency/refresh');await loadTab();toast(isEn ? 'Updated VND exchange rate.' : 'Đã cập nhật tỷ giá VND theo nguồn công bố.');}catch(error){toast(messageOf(error),'error');}finally{setFxBusy(false);}};
  const syncPending = async () => { setSyncing(true); try { const { data: backfill } = await api.post('/integrations/odoo/enqueue-unsynced'); const { data } = await api.post('/integrations/odoo/sync-pending'); const synced = data.results.filter((item: any) => item.status === 'SYNCED').length; const pending = data.results.length - synced; toast(isEn ? `Synced ${synced}/${data.attempted} records.` : `Đã đồng bộ ${synced}/${data.attempted} bản ghi; đưa thêm ${backfill.queued} mục cũ vào hàng đợi${pending ? `; ${pending} mục chờ xử lý` : ''}.`, pending ? 'info' : 'success'); await loadTab(); } catch (error) { toast(messageOf(error), 'error'); } finally { setSyncing(false); } };
