  const passwordFields: FieldDef[] = [{ name: 'currentPassword', label: isEn ? 'Current Password' : 'Mật khẩu hiện tại', type: 'password', required: true }, { name: 'newPassword', label: isEn ? 'New Password (at least 10 chars)' : 'Mật khẩu mới (tối thiểu 10 ký tự)', type: 'password', required: true }];
