  const saveRolePermissions = async (entry: any) => { try { await api.put(`/role-permissions/${entry.role}`, { entities: entry.entities, actions: entry.actions }); toast(isEn ? `Saved permissions for role ${entry.label}.` : `Đã lưu quyền cho vai trò ${entry.label}.`); await loadTab(); window.location.reload(); } catch (error) { toast(messageOf(error), 'error'); } };
